            rejected += 1
            continue
        results.append({
            'index': idx,
            'decision': decision,
            'first': first,
            'account': acct,
            'identity': identity,
            'from': out_from,
            'pai': out_pai,
            'method': method,
            'target': target,
            'call_id': call_id,
            'cseq': cseq,
            'tag': tag,
            'privacy': privacy,
            'body_sha256': digest.hex(),
        })

    out = {'results': results, 'accepted': accepted, 'replayed': replayed,
           'rejected': rejected, 'live': len(ledger)}
