    lu = len(user)
    if lu < 1 or lu > 64:
        return None
    j = ue + 1
    m2 = _HOST_RUN_RE.match(s, j)
    he = m2.end()
    host = s[j:he]
    if len(host) < 3 or len(host) > 253:
        return None
    labels = host.split('.')
    if len(labels) < 2:
        return None
    for lab in labels:
        if len(lab) > 63 or not _LABEL_RE.match(lab):
            return None
    if labels[-1][0] not in _ALPHA:
        return None                     # final label begins with a letter
    j = he
    port_txt = None
    if j < n and s[j] == ':':
        j += 1
        m3 = _DIGIT_RUN_RE.match(s, j)
        pe = m3.end()
        pd = s[j:pe]
        if len(pd) < 1 or len(pd) > 5:
            return None
        pv = int(pd)
        if pv < 1 or pv > 65535:
            return None
        port_txt = str(pv)
        j = pe
    canon = kind + ':' + user + '@' + host.lower()
    if port_txt is not None:
        canon = canon + ':' + port_txt
    return (kind, canon, j)


def _bracket(s, k):
    """Parse '<URI>' starting at s[k] == '<'."""
    gt = s.find('>', k + 1)
    if gt < 0:
        return None
    inner = s[k + 1:gt]
    if not inner:
        return None
    if ' ' in inner or '\t' in inner:
        return None                     # no whitespace inside brackets
    r = parse_uri_at(inner, 0)
    if r is None or r[2] != len(inner):
        return None
    return (r[0], r[1], s[gt + 1:])


def parse_address(s):
    """Parse one address from an OWS-stripped string.

    Returns (kind, canonical, rest) or None.
    """
    if not s:
        return None
    if s[0] == '"':
        m = _QUOTED_RE.match(s)
        if not m:
            return None
        k = m.end()
        n = len(s)
        while k < n and (s[k] == ' ' or s[k] == '\t'):
            k += 1
        if k >= n or s[k] != '<':
            return None                 # only SP/HTAB may follow the quote
        return _bracket(s, k)
    lt = s.find('<')
    if lt < 0:
        r = parse_uri_at(s, 0)
        if r is None:
            return None
        return (r[0], r[1], s[r[2]:])
    if lt > 0 and not _DISPLAY_RE.match(s[:lt]):
        return None
    return _bracket(s, lt)


# ------------------------------------------------- field grammar
def parse_from_field(value):
    """From: exactly one address plus exactly one ;tag=TOKEN."""
    r = parse_address(value)
    if r is None:
        return None
    kind, canon, rest = r
    i = 0
    n = len(rest)
    while i < n and (rest[i] == ' ' or rest[i] == '\t'):
        i += 1
    if i >= n or rest[i] != ';':
        return None
    i += 1
    while i < n and (rest[i] == ' ' or rest[i] == '\t'):
        i += 1
    if rest[i:i + 3].lower() != 'tag':
        return None
    i += 3
    while i < n and (rest[i] == ' ' or rest[i] == '\t'):
        i += 1
    if i >= n or rest[i] != '=':
        return None
    i += 1
    while i < n and (rest[i] == ' ' or rest[i] == '\t'):
        i += 1
    m = _TOKEN_RUN_RE.match(rest, i)
    te = m.end()
    tag = rest[i:te]
    if len(tag) < 1 or len(tag) > 32:
        return None
    if te != n:
        return None                     # no other parameters, no junk
    return (kind, canon, tag)


def parse_cseq(value, method):
    parts = _CSEQ_SPLIT_RE.split(value)
    if len(parts) != 2:
        return None
    num, meth = parts
    ln = len(num)
    if ln < 1 or ln > 10:
        return None
    for ch in num:
        if ch not in _DIGITS:
            return None
    v = int(num)
    if v < 1 or v > 2147483647:
        return None
    if meth != method:
        return None
    return v


def _split_commas(s):
    """Split a header row on commas outside quoted names and angle brackets."""
    if '"' not in s and '<' not in s:
        return s.split(',')
    parts = []
    cur = []
    i = 0
    n = len(s)
    inq = False
    inb = False
    while i < n:
        c = s[i]
        if inq:
            if c == '\\' and i + 1 < n:
                cur.append(c)
                cur.append(s[i + 1])
                i += 2
                continue
            if c == '"':
                inq = False
            cur.append(c)
        elif inb:
            if c == '>':
                inb = False
            cur.append(c)
        else:
            if c == ',':
                parts.append(''.join(cur))
                cur = []
            else:
                if c == '"':
                    inq = True
                elif c == '<':
                    inb = True
                cur.append(c)
        i += 1
    parts.append(''.join(cur))
    return parts


