def parse_identity_list(rows):
    """PAI/PPI: None when absent, INVALID on error, else [(kind, canon)]."""
    if rows is None:
        return None
    items = []
    for row in rows:
        for it in _split_commas(row):
            items.append(it.strip(' \t'))
    parsed = []
    for it in items:
        if not it:
            return INVALID               # empty item or empty row
        r = parse_address(it)
        if r is None or r[2] != '':
            return INVALID               # no header parameters
        parsed.append((r[0], r[1]))
    if not parsed or len(parsed) > 2:
        return INVALID
    if len(parsed) == 2:
        if parsed[0][0] == 'tel':
            if parsed[1][0] == 'tel':
                return INVALID
            parsed = [parsed[1], parsed[0]]
        elif parsed[1][0] != 'tel':
            return INVALID               # two SIP/SIPS URIs are invalid
    return parsed


def parse_privacy(rows):
    if rows is None:
        return 'absent'
    val = None
    for row in rows:
        for item in row.split(';'):
            t = item.strip(' \t').lower()
            if t != 'id' and t != 'none':
                return INVALID
            if val is None:
                val = t
            elif val != t:
                return INVALID           # mixing id and none
    if val is None:
        return INVALID
    return val


# ------------------------------------------------- request parsing
def parse_request(data):
    """Decode one SIP request; raises Reject with the proper stage reason."""
    if len(data) > 65536:
        raise Reject('syntax')
    pos = data.find(b'\r\n\r\n')
    if pos < 0:
        raise Reject('syntax')
    hb = data[:pos]
    body = data[pos + 4:]
    if len(hb) > 32768:
        raise Reject('syntax')
    lines = hb.split(b'\r\n')
    if len(lines) > 257:
        raise Reject('syntax')           # start line + at most 256 headers
    for ln in lines:
        if len(ln) > 8192 or _BAD_LINE_RE.search(ln) is not None:
            raise Reject('syntax')
    sl = lines[0].decode('ascii')
    sp = sl.split(' ')
    if len(sp) != 3:
        raise Reject('syntax')
    method = sp[0]
    if method != 'INVITE' and method != 'MESSAGE':
        raise Reject('syntax')
    if sp[2] != 'SIP/2.0':
        raise Reject('syntax')
    r = parse_uri_at(sp[1], 0)
    if r is None or r[0] == 'tel' or r[2] != len(sp[1]):
        raise Reject('syntax')
    target = r[1]
    headers = []
    for k in range(1, len(lines)):
        raw = lines[k].decode('ascii')
        if raw[:1] == ' ' or raw[:1] == '\t':
            if not headers:
                raise Reject('syntax')   # continuation without a header
            nm, val = headers[-1]
            headers[-1] = (nm, val.rstrip(' \t') + ' ' + raw.lstrip(' \t'))
        else:
            ci = raw.find(':')
            if ci < 0:
                raise Reject('syntax')
            nb = raw[:ci].rstrip(' \t')
            if not _TOKEN_RE.match(nb):
                raise Reject('syntax')   # empty or non-token field name
            low = nb.lower()
            headers.append((_COMPACT.get(low, low), raw[ci + 1:]))
    counts = {}
    values = {}
    for nm, val in headers:
        counts[nm] = counts.get(nm, 0) + 1
        v = val.strip(' \t')
        if nm in _MULTI:
            if nm in values:
                values[nm].append(v)
            else:
                values[nm] = [v]
        else:
            values[nm] = v
    for nm in _REQ5:
        if counts.get(nm, 0) != 1:
            raise Reject('headers')
    cl = values['content-length']
    if not cl or len(cl) > 10:
        raise Reject('length')
    for ch in cl:
        if ch not in _DIGITS:
            raise Reject('length')
    if int(cl) != len(body):
        raise Reject('length')
    fr = parse_from_field(values['from'])
    if fr is None:
        raise Reject('fields')
    from_canon = fr[1]
    tag = fr[2]
    tr = parse_address(values['to'])
    if tr is None or tr[2] != '' or tr[0] == 'tel' or tr[1] != target:
        raise Reject('fields')
    call_id = values['call-id']
    if not _CALLID_RE.match(call_id):
        raise Reject('fields')
    cseq = parse_cseq(values['cseq'], method)
    if cseq is None:
        raise Reject('fields')
    pai = parse_identity_list(values.get('p-asserted-identity'))
    if pai is INVALID:
        raise Reject('fields')
    ppi = parse_identity_list(values.get('p-preferred-identity'))
    if ppi is INVALID:
        raise Reject('fields')
    privacy = parse_privacy(values.get('privacy'))
    if privacy is INVALID:
        raise Reject('fields')
    return (method, target, call_id, cseq, from_canon, tag, pai, ppi, privacy,
            body)


# ------------------------------------------------- envelope
def strict_loads(raw):
    if raw[:3] == b'\xef\xbb\xbf':
        raise EnvelopeError('bom')
    text = raw.decode('utf-8')           # strict: rejects malformed UTF-8

    def no_const(_x):
        raise EnvelopeError('non-finite number')

    def no_float(_x):
        raise EnvelopeError('fractional or exponent number')

    def pairs(pairs):
        d = {}
        for k, v in pairs:
            if k in d:
                raise EnvelopeError('duplicate object key')
            d[k] = v
        return d

    return json.loads(text, object_pairs_hook=pairs, parse_constant=no_const,
                      parse_float=no_float)


def _exact_keys(obj, keys):
    if not isinstance(obj, dict):
        raise EnvelopeError('not an object')

        raise EnvelopeError('not an object')
    if set(obj.keys()) != keys:
        raise EnvelopeError('key set')
    return obj


def _int_field(v, lo, hi):
    if type(v) is not int:               # excludes bool and non-integers
        raise EnvelopeError('integer')
    if v < lo or v > hi:
        raise EnvelopeError('integer range')
    return v


def validate_envelope(doc):
    _exact_keys(doc, frozenset(('version', 'config', 'events')))
    if type(doc['version']) is not int or doc['version'] != 1:
        raise EnvelopeError('version')
    cfg = _exact_keys(doc['config'],
                      frozenset(('accounts', 'peers', 'ttl_ms', 'capacity')))
    accounts = cfg['accounts']
    if not isinstance(accounts, list) or len(accounts) > 256:
        raise EnvelopeError('accounts')
    acct_ids = set()
    alias_owner = {}
    acct_default = {}
    for a in accounts:
        _exact_keys(a, frozenset(('id', 'default', 'aliases')))
        aid = a['id']
        if not isinstance(aid, str) or not _ID_RE.match(aid) or aid in acct_ids:
            raise EnvelopeError('account id')
        acct_ids.add(aid)
        aliases = a['aliases']
        if not isinstance(aliases, list) or len(aliases) < 1 or len(aliases) > 8:
            raise EnvelopeError('aliases')
        seen = set()
        for al in aliases:
            if not isinstance(al, str):
                raise EnvelopeError('alias type')
            r = parse_uri_at(al, 0)
            if r is None or r[2] != len(al) or r[1] != al:
                raise EnvelopeError('alias not canonical')
            if r[1] == ANON:
                raise EnvelopeError('anonymous alias')
            if al in seen or al in alias_owner:
                raise EnvelopeError('alias ownership')
            seen.add(al)
            alias_owner[al] = aid
        dflt = a['default']
        if not isinstance(dflt, str) or dflt not in seen:
            raise EnvelopeError('default alias')
        acct_default[aid] = dflt
    peers = cfg['peers']
    if not isinstance(peers, list) or len(peers) < 1 or len(peers) > 256:
        raise EnvelopeError('peers')
    peer_ids = set()
    peer_info = {}
    for p in peers:
        _exact_keys(p, frozenset(('id', 'mode', 'accounts')))
        pid = p['id']
        if not isinstance(pid, str) or not _ID_RE.match(pid) or pid in peer_ids:
            raise EnvelopeError('peer id')
        peer_ids.add(pid)
        mode = p['mode']
        if mode == 'access':
            if p['accounts'] != []:
                raise EnvelopeError('access peer accounts')
            allowed = frozenset()
        elif mode == 'relay':
            pac = p['accounts']
            if not isinstance(pac, list):
                raise EnvelopeError('relay accounts type')
            if len(set(pac)) != len(pac):
                raise EnvelopeError('relay accounts distinct')
            for x in pac:
                if not isinstance(x, str) or x not in acct_ids:
                    raise EnvelopeError('relay account id')
            allowed = frozenset(pac)
        else:
            raise EnvelopeError('peer mode')
        peer_info[pid] = (mode, allowed)
    ttl = _int_field(cfg['ttl_ms'], 1, 1000000)
    cap = _int_field(cfg['capacity'], 1, 10000)
    events = doc['events']
    if not isinstance(events, list) or len(events) > 10000:
        raise EnvelopeError('events')
    ev_list = []
    prev_t = None
    for e in events:
        _exact_keys(e, frozenset(('t', 'peer', 'auth', 'egress', 'wire_hex')))
        t = _int_field(e['t'], 0, MAX_T)
        if prev_t is not None and t < prev_t:
            raise EnvelopeError('descending time')
        prev_t = t
        pid = e['peer']
        if not isinstance(pid, str) or pid not in peer_ids:
            raise EnvelopeError('peer id')
        auth = e['auth']
        if auth is not None:
            if not isinstance(auth, str) or auth not in acct_ids:
                raise EnvelopeError('auth id')
        if peer_info[pid][0] == 'relay' and auth is not None:
            raise EnvelopeError('relay auth')
        eg = e['egress']
        if eg != 'internal' and eg != 'external':
            raise EnvelopeError('egress')
        wh = e['wire_hex']
        if not isinstance(wh, str) or len(wh) > 131072:
            raise EnvelopeError('wire_hex')
        ev_list.append((t, pid, auth, eg, wh))
    return acct_default, alias_owner, peer_info, ttl, cap, ev_list


# ------------------------------------------------- policy
def apply_policy(mode, allowed, auth, pai, ppi, privacy, from_canon,
                 acct_default, alias_owner):
    """Sections 4 and 6-7: returns (account, identity, asserted list)."""
    if mode == 'access':
        if ppi is not None:
            for _k, u in ppi:
                if alias_owner.get(u) != auth:
                    raise Reject('identity')
            asserted = [u for _k, u in ppi]
            identity = asserted[0]
        else:
            identity = acct_default[auth]
            asserted = [identity]
        acct = auth
    else:
        if ppi is not None:
            raise Reject('identity')     # PPI must be absent on a relay
        if pai is None:
            raise Reject('identity')     # PAI must be present on a relay
        owner = None
        for _k, u in pai:
            o = alias_owner.get(u)
            if o is None:
                raise Reject('identity')
            if owner is None:
                owner = o
            elif owner != o:
                raise Reject('identity')
        if owner not in allowed:
            raise Reject('identity')
        acct = owner
        asserted = [u for _k, u in pai]
        identity = asserted[0]
    if alias_owner.get(from_canon) != acct:
        if from_canon != ANON or privacy != 'id':
            raise Reject('identity')
    return acct, identity, asserted


# ------------------------------------------------- main
def main():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        return 2
    try:
        doc = strict_loads(raw)
    except Exception:
        return 2
    del raw
    try:
        acct_default, alias_owner, peer_info, ttl, cap, ev_list = \
            validate_envelope(doc)
    except EnvelopeError:
        return 2
    del doc

